import cv2

def capture_gray():
    cap = cv2.VideoCapture(0)
    try:
        ok, frame = cap.read()
        if not ok:
            raise RuntimeError('camera read failed')
        return cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    finally:
        cap.release()

